CREATE TABLE sys_user (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  username VARCHAR(64) NOT NULL UNIQUE,
  password_hash VARCHAR(100) NOT NULL,
  display_name VARCHAR(80) NOT NULL,
  email VARCHAR(128), status VARCHAR(16) NOT NULL DEFAULT 'ENABLED',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), deleted TINYINT NOT NULL DEFAULT 0
);
CREATE TABLE sys_role (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, description VARCHAR(255), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), deleted TINYINT NOT NULL DEFAULT 0);
CREATE TABLE sys_user_role (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id, role_id));
CREATE TABLE android_app (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, package_name VARCHAR(255) NOT NULL UNIQUE, app_name VARCHAR(120) NOT NULL, icon_object_key VARCHAR(500), description VARCHAR(1000), latest_release_id BIGINT,
  status VARCHAR(16) NOT NULL DEFAULT 'ENABLED', created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), deleted TINYINT NOT NULL DEFAULT 0
);
CREATE TABLE android_release (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, app_id BIGINT NOT NULL, version_code BIGINT NOT NULL, version_name VARCHAR(80) NOT NULL, build_no INT NOT NULL DEFAULT 1,
  original_filename VARCHAR(255) NOT NULL, object_key VARCHAR(500) NOT NULL, file_size BIGINT NOT NULL, sha256 CHAR(64) NOT NULL UNIQUE, signature_sha256 VARCHAR(128), min_sdk VARCHAR(32), target_sdk VARCHAR(32),
  release_notes TEXT, update_mode VARCHAR(16) NOT NULL DEFAULT 'NORMAL', status VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED', download_count BIGINT NOT NULL DEFAULT 0, uploaded_by BIGINT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), deleted TINYINT NOT NULL DEFAULT 0,
  INDEX idx_release_app_created(app_id, created_at), INDEX idx_release_app_version(app_id, version_code)
);
CREATE TABLE download_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, release_id BIGINT NOT NULL, ip VARCHAR(64), user_agent VARCHAR(500), downloaded_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_download_release_time(release_id, downloaded_at));
CREATE TABLE operation_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, username VARCHAR(64), action VARCHAR(80) NOT NULL, resource_type VARCHAR(80), resource_id VARCHAR(80), detail VARCHAR(1000), ip VARCHAR(64), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX idx_operation_created(created_at));
